board='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>For Mother Russia — Chapter Production Board</title><style>:root{--navy:#081c31;--blue:#1e507d;--gold:#f6c16e;--ice:#cadff1;--paper:#f7f1e5;--line:#426989}*{box-sizing:border-box}body{margin:0;background:var(--navy);color:var(--paper);font:15px/1.55 system-ui,Arial,sans-serif}header{padding:40px 5vw 20px;border-bottom:1px solid var(--line)}header h1{font:normal clamp(37px,5vw,72px)/1.1 Georgia,serif;margin:14px 0}header .eyebrow{color:var(--gold);font:12px monospace;letter-spacing:.1em}.hero{display:grid;grid-template-columns:minmax(250px,.9fr) 1.3fr;gap:25px;align-items:center;margin:28px 0}.hero img{width:100%;aspect-ratio:16/10;object-fit:cover;border:1px solid var(--gold)}.hero p{font-size:20px;color:var(--ice)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:24px 5vw}.stat{border:1px solid var(--line);background:#153852;padding:16px}.stat strong{font-size:31px;display:block}.stat span{font:11px monospace;color:var(--ice)}.bar{margin:0 5vw 30px;background:#344961;height:13px}.fill{background:var(--gold);height:100%;width:0%}.layout{padding:10px 5vw 70px;display:grid;grid-template-columns:250px 1fr;gap:23px}.control{background:#102d46;padding:20px;border:1px solid var(--line);align-self:start;position:sticky;top:20px}.control label{display:block;font:11px monospace;margin:11px 0 5px}.control input,.control select{width:100%;padding:10px;background:#061724;color:var(--paper);border:1px solid var(--line)}button{cursor:pointer}.export{padding:11px;border:1px solid var(--gold);background:var(--gold);color:#071b31;width:100%;margin-top:22px;font-weight:bold}.overview{border:1px solid var(--line);padding:20px;background:#102e46;margin-bottom:16px}.overview h2{margin:0 0 10px;font:29px Georgia,serif}.tasks{display:grid;gap:8px}.task{display:grid;grid-template-columns:60px 1fr 140px;align-items:center;gap:12px;padding:13px;border:1px solid #365974;background:#102e45}.task small{color:var(--gold);font:12px monospace}.task h3{font-size:14px;margin:0}.task p{color:#a8bfd0;font:11px/1.5 monospace;margin:5px 0 0}.task select{padding:8px;background:#0a2137;color:var(--paper);border:1px solid var(--line)}.note{font:12px/1.7 monospace;color:#b7c9d9;margin-top:30px}footer{border-top:1px solid var(--line);padding:25px 5vw;font:11px monospace;color:var(--ice)}@media(max-width:750px){.hero,.layout{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}.control{position:static}.task{grid-template-columns:34px 1fr}.task select{grid-column:2;max-width:210px}}</style></head><body><header><div class="eyebrow">.json / 03 — PRODUCTION CONTROL / REVIEW PROOF</div><div class="hero"><div><h1>For Mother Russia</h1><p>Some places live in you even if you have never been there. Blue winter, a yellow beanie, all black and Gấu, amid images borrowed from childhood imagination.</p></div><img alt="Chapter cover concept featuring Jason in yellow beanie and white fluffy Gấu in a winter landscape" src="../art/01_HERO_beanie_Gau_blue_winter.jpg"></div></header><div class="stats" id="stats"></div><div class="bar"><div class="fill" id="fill"></div></div><div class="layout"><aside class="control"><label for="q">SEARCH TASKS</label><input id="q" placeholder="search..." autocomplete="off"><label for="stream">WORKSTREAM</label><select id="stream"><option value="">All workstreams</option></select><label for="status">STATUS</label><select id="status"><option value="">All statuses</option><option>READY</option><option>PROOF</option><option>TODO</option><option>BLOCKED</option><option>IN_PROGRESS</option></select><button class="export" id="export">Export updated CSV</button><p class="note">Changes are saved only in this browser, not synced to GitHub. Export CSV for durable tracking. READY means the current deliverable has been verified; proofs are not final commercial assets.</p></aside><section><div class="overview"><h2>Chapter asset production</h2><p><strong>Editorial:</strong> original and a minimal revision. <strong>Visual:</strong> winter poster, cabin, salad, family, game imagery. <strong>Book:</strong> A5 editorial proof. <strong>Digital:</strong> seven-node Memory Graph and full reader. <strong>Video:</strong> ambient-only 24s proof. <strong>Distribution:</strong> social drafts; approvals and live deployment still pending.</p></div><div class="tasks" id="tasks"></div></section></div><footer>.json — For Mother Russia / Chapter 03 · No tracking, no private content uploaded to a server by this board.</footer><script>const baseline=__JSON__;const storageKey='json-russia-ch03-board';let saved={};try{saved=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch{}let rows=baseline.map(x=>({...x,status:saved[x.id]||x.status}));let $=x=>document.getElementById(x);let streams=[...new Set(rows.map(x=>x.stream))];streams.forEach(s=>{let o=document.createElement('option');o.value=o.textContent=s;$('stream').append(o)});function render(){let count={};['READY','PROOF','TODO','BLOCKED','IN_PROGRESS'].forEach(s=>count[s]=rows.filter(x=>x.status===s).length);$('stats').innerHTML=['READY','PROOF','TODO','BLOCKED'].map(s=>'<div class="stat"><strong>'+count[s]+'</strong><span>'+s+'</span></div>').join('');$('fill').style.width=String(count.READY/rows.length*100)+'%';let q=$('q').value.toLowerCase(),stream=$('stream').value,status=$('status').value;let filtered=rows.filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!stream||x.stream===stream)&&(!status||x.status===status));$('tasks').replaceChildren();filtered.forEach(r=>{let t=document.createElement('article');t.className='task';let id=document.createElement('small');id.textContent=r.id;let body=document.createElement('div');let title=document.createElement('h3');title.textContent=r.title;let info=document.createElement('p');info.textContent=r.stream+' / '+r.priority+' / '+r.acceptance;body.append(title,info);let sel=document.createElement('select');['READY','PROOF','TODO','BLOCKED','IN_PROGRESS'].forEach(s=>{let o=document.createElement('option');o.value=o.textContent=s;sel.append(o)});sel.value=r.status;sel.setAttribute('aria-label','Status for '+r.title);sel.onchange=()=>{r.status=sel.value;let m={};rows.forEach(x=>m[x.id]=x.status);try{localStorage.setItem(storageKey,JSON.stringify(m))}catch{}render()};t.append(id,body,sel);$('tasks').append(t)})}['q','stream','status'].forEach(id=>$(id).addEventListener(id==='q'?'input':'change',render));$('export').onclick=()=>{const cols=['id','stream','title','status','owner','priority','acceptance'];let text=[cols.join(','),...rows.map(r=>cols.map(k=>'"'+String(r[k]||'').replaceAll('"','""')+'"').join(','))].join('\\r\\n');let blob=new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Mother_Russia_updated_tasks.csv';a.click();URL.revokeObjectURL(a.href)};render()</script></body></html>'''
